126	/**
127	 * Shared function to check email status with the promptfoo API
128	 * Used by both CLI and server routes
129	 */
130	export async function checkEmailStatus(options?: {
131	  validate?: boolean;
132	}): Promise<EmailStatusResult> {
133	  const { default: telemetry } = await import('../telemetry');
134	  const ciMode = isCI();
135	  const userEmail = ciMode ? CI_PLACEHOLDER_EMAIL : getUserEmail();
136	
137	  if (!userEmail) {
138	    return {
139	      status: NO_EMAIL_STATUS,
140	      hasEmail: false,
141	      message: 'Redteam evals require email verification. Please enter your work email:',
142	    };
143	  }
144	
145	  if (ciMode) {
146	    // CI uses a synthetic placeholder to avoid interactive prompts. Treat it as
147	    // already validated so test runs do not depend on live account state.
148	    return {
149	      status: EmailValidationStatus.OK,
150	      hasEmail: true,
151	      email: userEmail,
152	    };
153	  }
154	
155	  try {
156	    const validateParam = options?.validate ? '&validate=true' : '';
157	    // Use longer timeout when validation is requested
158	    const timeout = options?.validate ? 3000 : 500;
159	
160	    // Log when we're validating the email since it can take a sec
161	    if (options?.validate) {
162	      logger.info(`Checking email...`);
163	    }
164	
165	    const host = getEnvString('PROMPTFOO_CLOUD_API_URL', 'https://api.promptfoo.app');
166	
167	    const resp = await fetchWithTimeout(
168	      `${host}/api/users/status?email=${encodeURIComponent(userEmail)}${validateParam}`,
169	      undefined,
170	      timeout,
171	    );
172	    const data = (await resp.json()) as {
173	      status: EmailValidationStatus;
174	      message?: string;
175	      error?: string;
176	    };
177	
178	    if (options?.validate) {
179	      const invalidStatuses: Set<EmailValidationStatus> = new Set([
180	        EmailValidationStatus.RISKY_EMAIL,
181	        EmailValidationStatus.DISPOSABLE_EMAIL,
182	        EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED,
183	      ]);
184	      if (invalidStatuses.has(data.status)) {
185	        if (data.status === EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED) {
186	          setUserEmailValidated(false);
187	          setUserEmailNeedsValidation(true);
188	        }
189	        // Tracking filtered emails via this telemetry endpoint for now to guage sensitivity of validation
190	        // We should take it out once we're happy with the sensitivity
191	        if (
192	          data.status === EmailValidationStatus.RISKY_EMAIL ||
193	          data.status === EmailValidationStatus.DISPOSABLE_EMAIL
194	        ) {
195	          await telemetry.saveConsent(userEmail, {
196	            source: 'filteredInvalidEmail',
197	          });
198	        }
199	      } else {
200	        setUserEmailValidated(true);
201	        // Track the validated email via telemetry
202	        await telemetry.saveConsent(userEmail, {
203	          source: 'promptForEmailValidated',
204	        });
205	      }
206	    }
207	
208	    return {
209	      status: data.status,
210	      message: data.message ?? data.error,
211	      email: userEmail,
212	      hasEmail: true,
213	    };
214	  } catch (e) {
215	    logger.debug(`Failed to check user status: ${e}`);
216	    // If we can't check status, assume it's OK but log the issue
217	    return {
218	      status: EmailValidationStatus.OK,
219	      message: 'Unable to verify email status, but proceeding',
220	      email: userEmail,
221	      hasEmail: true,
222	    };
223	  }
224	}
